请对以下 case 进行三维加权评分。

=== case_id ===
Case-24-todo-015

=== 用户原始指令 (query.txt) ===
来一张主题色背景的待办卡,中间圆环显示整体完成度,下面竖着排可勾选的任务,某项临近截止要黄色待处理提示,点任务能跳到天气详情页,读天气数据,勾选前面用对号图标。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "来一张主题色背景的待办卡,中间圆环显示整体完成度,下面竖着排可勾选的任务,某项临近截止要黄色待处理提示,点任务能跳到天气详情页,读天气数据,勾选前面用对号图标。",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hww://www.huawei.com/totemweather?enterType=share&cityCode="
      }
    }
  ],
  "dataModelSchema": {
    "todo": {
      "title": {
        "type": "string",
        "description": "待办卡标题。",
        "sampleValue": "今日待办"
      },
      "progressValue": {
        "type": "number",
        "description": "整体完成度数值。",
        "sampleValue": 75
