      "progressTotal": {
        "type": "number",
        "description": "完成度总量。",
        "sampleValue": 100
      },
      "progressText": {
        "type": "string",
        "description": "整体完成度展示文本。",
        "sampleValue": "75%"
      },
      "task0": {
        "title": {
          "type": "string",
          "description": "第一项待办任务名称。",
          "sampleValue": "查看天气"
        },
        "checked": {
          "type": "boolean",
          "description": "第一项任务是否已勾选。",
          "sampleValue": true
        }
      },
      "task1": {
        "title": {
          "type": "string",
          "description": "第二项待办任务名称。",
          "sampleValue": "带伞提醒"
        },
        "checked": {
          "type": "boolean",
          "description": "第二项任务是否已勾选。",
          "sampleValue": false
        },
        "statusText": {
          "type": "string",
          "description": "临近截止任务的黄色待处理提示文案。",
          "sampleValue": "待处理"
        }
      },
      "task2": {
        "title": {
          "type": "string",
          "description": "第三项待办任务名称。",
          "sampleValue": "防晒检查"
        },
        "checked": {
          "type": "boolean",
          "description": "第三项任务是否已勾选。",
          "sampleValue": true
        }
      }
    },
    "data": {
      "weather": {
        "location": {
          "cityCode": {
            "type": "string",
            "description": "天气详情页使用的城市代码。",
            "sampleValue": "60814"
          },
          "districtName": {
            "type": "string",
            "description": "天气查询地区名称。",
            "sampleValue": "青浦"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本。",
            "sampleValue": "29°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象。",
            "sampleValue": "多云"
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/checkmark_calendar_fill.svg",
      "description": "带对勾的日历实心图标，适合表达待办完成、任务清单或日程确认。"
    }
  ]
}

